-- story.0090: @cogni/agent-grants 0.10.0 carries the org columns on every node; they stay null until a node adopts orgs. Expand only (add columns, widen one CHECK).
-- Generated by drizzle-kit from this node's schema; the owner block below is the only hand-written part. Same role handling as 0035/0037: act as the non-bypass owner of public.users
-- so ALTER TABLE on agent_principals works whether this runs alone or after 0035 in one transaction.
DO $$
DECLARE owner_name text;
BEGIN
  SELECT r.rolname INTO owner_name FROM pg_class c JOIN pg_roles r ON r.oid = c.relowner
  WHERE c.oid = 'public.users'::regclass AND NOT r.rolsuper AND NOT r.rolbypassrls;
  IF owner_name IS NULL OR NOT pg_has_role(current_user, owner_name, 'MEMBER') THEN
    RAISE EXCEPTION 'org expand requires membership in the non-bypass users owner';
  END IF;
  EXECUTE format('SET LOCAL ROLE %I', owner_name);
END $$;
